use super::{language, Language};

// Keep each message's stable ID and complete English and Spanish forms together.
macro_rules! catalog {
    ($($id:ident => ($english:literal, $spanish:literal),)+) => {
        #[derive(Clone, Copy)]
        pub enum Text {
            $($id,)+
        }

        impl Text {
            pub fn get(self) -> &'static str {
                match (language(), self) {
                    $((Language::English, Self::$id) => $english,
                      (Language::Spanish, Self::$id) => $spanish,)+
                }
            }
        }
    };
}

